with feeders as (
    select
        md5(upper('HUB_CASE|' || (HUB_CASE_BK__CASHLESS_IN_ID))) as HUB_CASE_HK
        , REDIRECT_FLAG as REDIRECT_INDICATOR
        , 'BJAZ_HM_INWARD_OMNI_MAPPING' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_inward_omni_mapping') }}
    where (nullif(trim(CASHLESS_IN_ID),'')) is not null
),

resolved as (
    select
        HUB_CASE_HK,
        max(case when SOURCE_RUN = 'opus_health_v2' then REDIRECT_INDICATOR end) as REDIRECT_INDICATOR,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_CASE_HK
),

hashed as (
    select
        *,
        case when REDIRECT_INDICATOR is not null
                     then md5(upper(coalesce(cast(REDIRECT_INDICATOR as varchar), '')))
                end as SAT_CASE_EXTERNAL_REF_HASHDIFF
    from resolved
)

select * from hashed
where HUB_CASE_HK is not null
  and SAT_CASE_EXTERNAL_REF_HASHDIFF is not null
